use crate::{core_api::{self,Action},engine::Engine,model::*,purposes,rpc::Rpc,setup::Settings,sns_team};
use serde_json::{json,Value};
use std::{fs,path::PathBuf,sync::{Arc,atomic::Ordering},time::{Duration,Instant}};
fn research()->Value{json!({"topic":"小さく始める","evidenceScope":"PROVIDED_INPUT_ONLY","providedFacts":["提供されたテーマは小さく始める"],"candidateAngles":["日々の小さな一歩"],"unknowns":[],"limitations":["外部資料との照合は行っていない"]})}
fn fixture(label:&str)->(PathBuf,Arc<Engine>){
 let p=PathBuf::from(std::env::var_os("AI_GUILD_TEST_ROOT").expect("isolated root required")).join(format!("sns-team-{label}-{}",id()));fs::create_dir_all(p.join("output")).unwrap();fs::write(p.join(".ai-guild-qa"),"OFFLINE three-person only").unwrap();let e=Engine::open(&p,None).unwrap();
 e.save_setup(Settings{work_root:p.to_string_lossy().into(),output_root:p.join("output").to_string_lossy().into(),approval_policy:"on-request".into(),..Default::default()}).unwrap();
 fs::write(p.join("offline-research.json"),research().to_string()).unwrap();
 fs::write(p.join("offline-plan.json"),json!({"title":"OFFLINE three-person","requirements":["小さく始める"],"checklist":["提供情報を保持"],"productionConstraints":["外部照合未実施、ローカル納品のみ"],"files":[{"name":"post.txt","requiredText":["小さく始める"]}],"testCommand":""}).to_string()).unwrap();
 fs::write(p.join("offline-event.html"),json!({"files":[{"name":"post.txt","content":"小さく始める。日々の一歩を、少しずつ。"}]}).to_string()).unwrap();*e.rpc.lock().unwrap()=Some(Rpc::phase9_fixture(&p).unwrap());e.update(|s|{s.connection.status="connected".into();Ok(())}).unwrap();(p,e)
}
fn wait(e:&Engine){let end=Instant::now()+Duration::from_secs(20);while e.worker.load(Ordering::SeqCst)&&Instant::now()<end{std::thread::sleep(Duration::from_millis(20));}assert!(!e.worker.load(Ordering::SeqCst),"OFFLINE peer timeout")}
fn start(e:&Arc<Engine>)->String{let result=core_api::perform(e,Action::StartPurpose{purpose_id:purposes::SOCIAL.into(),definition_version:purposes::VERSION.into(),input:json!({"theme":"小さく始める。外部投稿不要。","contentLanguage":"ja"}),completion_plan:None}).unwrap();wait(e);result["jobId"].as_str().unwrap().into()}
#[test]fn sns_team_four_people_three_codex_stages_no_human_gate_and_restart(){
 let(p,e)=fixture("complete");let id=start(&e);let s=e.snapshot();let j=s.job.as_ref().unwrap();assert_eq!(j.status,"completed");assert_eq!(j.workflow_id,sns_team::DECISIONS_ID);assert_eq!(j.practical.as_ref().unwrap().turn_starts,3);assert_eq!(j.practical.as_ref().unwrap().max_turn_starts,3);assert!(s.approvals.is_empty());assert!(!j.nodes.contains_key(crate::sns::REVIEW));assert!(!s.events.iter().any(|v|v.event_type=="content_review_requested"));assert_eq!(s.purpose_job_context[&id].definition_version,purposes::VERSION);
 let frame=e.presentation_snapshot(&id).unwrap();assert_eq!(frame["jobStatus"],"SUCCEEDED");assert_eq!(frame["roleMapVersion"],sns_team::ROLE_MAP);assert_eq!(frame["roles"].as_array().unwrap().iter().map(|r|r["id"].as_str().unwrap()).collect::<Vec<_>>(),["researcher","director","creator","inspector"]);
 for (node,role) in [("writing","creator"),("qa","inspector"),("delivery","inspector")]{assert!(frame["tasks"].as_array().unwrap().iter().any(|t|t["nodeId"]==node&&t["roleId"]==role));}assert_eq!(j.quality.as_ref().unwrap().machine_status,"PASS");crate::sns::approved(j).unwrap();
 let rows=fs::read_to_string(p.join("offline-peer.jsonl")).unwrap().lines().map(|s|serde_json::from_str::<Value>(s).unwrap()).collect::<Vec<_>>();let turns=rows.iter().filter(|r|r["event"]=="turn/start").collect::<Vec<_>>();assert_eq!(turns.len(),3);for(row,node)in turns.iter().zip(["research","plan","writing"]){assert_eq!(row["outputSchema"],crate::sns_output::for_job(j,node).unwrap());assert_eq!(row["sandboxPolicy"],crate::rpc::readonly_policy());}assert!(rows.iter().filter(|r|r["event"]=="research-input-check").all(|r|r["researchReceived"]==true));
 let post=j.artifacts.iter().find(|a|a.name=="post.txt").unwrap();let text=core_api::perform(&e,Action::ReadText{job_id:id.clone(),path:post.path.clone(),purpose:"copy".into()}).unwrap();assert_eq!(text["sha256"],post.sha256);assert!(!j.artifacts.iter().any(|a|a.name=="review.json"));assert!(j.artifacts.iter().any(|a|a.name=="manifest.json"));
 let check=json_file(j,"connector-check.json");assert_eq!(check["status"],"LOCAL_ONLY_NO_CONNECTION");assert_eq!(check["externalWrites"],0);assert_eq!(check["postSha256"],post.sha256);assert_eq!(check["publication"],"NOT_PERFORMED");assert!(json_file(j,"manifest.json")["artifacts"].as_array().unwrap().iter().any(|a|a["name"]=="connector-check.json"));
 fs::write(p.join("presentation-completed.json"),serde_json::to_vec_pretty(&frame).unwrap()).unwrap();fs::write(p.join("core-completed.json"),serde_json::to_vec_pretty(&core_api::snapshot(&s)).unwrap()).unwrap();
 let original=serde_json::to_value(j).unwrap();e.get_rpc().unwrap().shutdown();drop(e);let e=Engine::open(&p,None).unwrap();assert_eq!(serde_json::to_value(e.snapshot().job.unwrap()).unwrap(),original);assert_eq!(e.presentation_snapshot(&id).unwrap()["jobStatus"],"SUCCEEDED");
}
fn json_file(j:&Job,name:&str)->Value{serde_json::from_slice(&fs::read(&j.artifacts.iter().find(|a|a.name==name).unwrap().path).unwrap()).unwrap()}
#[test]fn sns_team_connected_connector_boundary_is_reached_without_send_or_remote_test(){
 let(p,e)=fixture("connected");
 let c=crate::providers::perform(&e,serde_json::from_value(json!({"operation":"connect","providerId":"mock","authMethod":"simulation","source":{"kind":"mock"},"fields":{"scenario":"success"}})).unwrap()).unwrap();
 crate::providers::perform(&e,serde_json::from_value(json!({"operation":"testConnection","connectionId":c["id"],"revision":1})).unwrap()).unwrap();
 let before=crate::providers::perform(&e,crate::providers::Action::Get).unwrap();start(&e);let s=e.snapshot();let j=s.job.as_ref().unwrap();assert_eq!(j.status,"completed");let check=json_file(j,"connector-check.json");assert_eq!(check["status"],"CONNECTOR_BOUNDARY_REACHED");assert_eq!(check["connectors"][0]["capabilityQuery"],"RETURNED");assert_eq!(check["connectors"][0]["scope"],"OFFLINE_SIMULATION");assert_eq!(check["remoteReachability"],"NOT_VERIFIED");assert_eq!(check["postingExecutor"],"NOT_IMPLEMENTED");assert_eq!(check["externalWrites"],0);assert_eq!(check["networkRequests"],0);assert_eq!(check["publication"],"NOT_PERFORMED");assert_eq!(crate::providers::perform(&e,crate::providers::Action::Get).unwrap(),before);assert!(s.approvals.is_empty());fs::write(p.join("connector-result.json"),serde_json::to_vec_pretty(&check).unwrap()).unwrap();e.get_rpc().unwrap().shutdown();
}
#[test]fn sns_team_invalid_research_stops_before_director_without_retry(){
 let(p,e)=fixture("bad-research");let mut r=research();r["evidenceScope"]=json!("WEB_SEARCHED");fs::write(p.join("offline-research.json"),r.to_string()).unwrap();start(&e);let s=e.snapshot();let j=s.job.as_ref().unwrap();assert_eq!(j.status,"failed");assert_eq!(j.practical.as_ref().unwrap().turn_starts,1);assert_eq!(j.nodes["plan"].attempt,0);assert!(j.artifacts.is_empty());assert!(s.approvals.is_empty());e.get_rpc().unwrap().shutdown();
}
#[test]fn sns_team_bad_product_cannot_reach_internal_quality_or_delivery(){
 let(p,e)=fixture("bad-product");fs::write(p.join("offline-event.html"),json!({"files":[{"name":"wrong.txt","content":"wrong"}]}).to_string()).unwrap();start(&e);let s=e.snapshot();let j=s.job.as_ref().unwrap();assert_eq!(j.status,"failed");assert_eq!(j.practical.as_ref().unwrap().turn_starts,3);assert_eq!(j.nodes["qa"].attempt,0);assert_eq!(j.nodes["delivery"].attempt,0);assert!(!j.artifacts.iter().any(|a|a.kind=="product"));assert!(s.approvals.is_empty());e.get_rpc().unwrap().shutdown();
}
#[test]fn sns_team_tamper_or_missing_research_cannot_be_success(){
 let(_,e)=fixture("tamper");let id=start(&e);let original=e.snapshot();let research=original.job.as_ref().unwrap().artifacts.iter().find(|a|a.name=="research.json").unwrap();let mut missing=original.clone();missing.job.as_mut().unwrap().artifacts.retain(|a|a.name!="research.json");assert!(crate::general::verify_product(missing.job.as_ref().unwrap()).is_err());
 fs::write(&research.path,"tampered").unwrap();assert!(crate::general::verify_product(original.job.as_ref().unwrap()).is_err());assert_eq!(e.presentation_snapshot(&id).unwrap()["jobStatus"],"UNKNOWN");e.get_rpc().unwrap().shutdown();
}
#[test]fn sns_team_stale_start_stops_before_new_job_and_keeps_legacy_hashes(){
 let(_,e)=fixture("stale");let before=serde_json::to_value(e.snapshot()).unwrap();for version in [purposes::LEGACY_VERSION,purposes::PRIOR_VERSION]{let input=json!({"theme":"旧Job","contentLanguage":"ja"});let p=purposes::prepare(purposes::SOCIAL,version,input.clone()).unwrap();assert!(p.workflow.nodes.iter().any(|n|n.node_id==crate::sns::REVIEW));assert!(!p.workflow.nodes.iter().any(|n|n.node_id=="research"));assert_eq!(p.context.role_map_version,purposes::ROLE_MAP_VERSION);assert!(core_api::perform(&e,Action::StartPurpose{purpose_id:purposes::SOCIAL.into(),definition_version:version.into(),input,completion_plan:None}).unwrap_err().starts_with("[PURPOSE_NOT_STARTED]"));}assert_eq!(serde_json::to_value(e.snapshot()).unwrap(),before);e.get_rpc().unwrap().shutdown();
}
